WITH daily_state_sales AS ( SELECT s.s_state, ss.ss_sold_date_sk, SUM(ss.ss_ext_sales_price) AS daily_sales, SUM(ss.ss_net_paid) AS daily_net_paid, COUNT(DISTINCT ss.ss_customer_sk) AS distinct_customers, AVG(c.c_birth_year) AS avg_birth_year FROM store_sales ss JOIN store s ON ss.ss_store_sk = s.s_store_sk JOIN customer c ON ss.ss_customer_sk = c.c_customer_sk JOIN household_demographics hd ON ss.ss_hdemo_sk = hd.hd_demo_sk GROUP BY s.s_state, ss.ss_sold_date_sk ) SELECT s_state, ss_sold_date_sk, daily_sales, daily_net_paid, distinct_customers, avg_birth_year, SUM(daily_sales) OVER (PARTITION BY s_state ORDER BY ss_sold_date_sk ROWS UNBOUNDED PRECEDING) AS cumulative_sales_state, AVG(daily_net_paid) OVER (PARTITION BY s_state ORDER BY ss_sold_date_sk ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS avg_7day_net_paid_state, RANK() OVER (ORDER BY total_state_sales DESC) AS state_sales_rank FROM ( SELECT *, SUM(daily_sales) OVER (PARTITION BY s_state) AS total_state_sales FROM daily_state_sales ) t WHERE ss_sold_date_sk BETWEEN 20230101 AND 20231231 ORDER BY s_state, ss_sold_date_sk
